export function behaviorServiceMarkup(editor,base,service,index){
 const path=base+'.services.'+index,query=service.kind==='query',field=(label,key,value,type='text',choices)=>editor.field(label,path+'.'+key,value,type,choices);
 return '<fieldset><legend>'+(query?'EQS 서비스':'이벤트 서비스')+'</legend>'+(query?editor.asset('환경 질의',path+'.asset',service.asset,['environmentquery'])+field('결과 키','key',service.key)+field('문맥 키','contextKey',service.contextKey||'')+field('결과','resultType',service.resultType,'text',[['actor','오브젝트'],['position','위치']])+field('성공 키','successKey',service.successKey||'')+field('완료 이벤트','event',service.event||''):field('이벤트','event',service.event))+field('간격','interval',service.interval,'number')+field('시간 편차','randomDeviation',service.randomDeviation??0,'number')+field('진입 시 갱신','callOnStart',service.callOnStart!==false,'checkbox')+field('재진입 시 시간 초기화','restartTimer',service.restartTimer!==false,'checkbox')+field('활성 이벤트','onActivation',service.onActivation||'')+field('비활성 이벤트','onDeactivation',service.onDeactivation||'')+'<button data-remove-service="'+index+'">삭제</button></fieldset>';
}
